// Level thumbnails: the real renderer, at overview framing, into a small
// offscreen canvas.
//
// WHY IT IS A RENDER AND NOT A FILE. Twenty PNGs checked into the repo would be
// stale the first time somebody edits a level, wrong the first time the art
// changes, and would have to be regenerated by a script nobody remembers to
// run. The two pieces needed to draw one already exist and are already correct:
// overview.ts frames a whole level (it is what TAB does), and artrender.ts
// draws the level. So a thumbnail is those two called with a smaller canvas —
// it cannot drift from the game, because it IS the game.
//
// THE RULES THAT KEEP IT OFF THE HOT PATH, which is the whole risk here:
//
//   * Nothing is rendered until the chooser is opened. A player who never opens
//     it never pays.
//   * ONE per animation frame, queued, and the queue is abandoned the moment
//     the chooser closes. Twenty renders in one frame would be a visible hitch
//     at exactly the moment somebody is looking at a menu.
//   * Results are cached for the session, keyed by simHash and size, so
//     reopening the chooser is free and the second open costs nothing at all.
//   * `measure: false` on the render call, so a thumbnail's cost never reaches
//     the adaptive-detail controller. Without it, opening the chooser would
//     feed twenty long frames into the thing that decides how much detail the
//     next second of PLAY gets — a menu quietly degrading the game.
//
// The level is drawn with the bike on the start line, on the shipped bike
// rather than the player's tuned one: a thumbnail is a picture of the level,
// and it must not change because somebody dragged a slider.
import { createSim } from '@/sim/sim.ts';
import { cloneSpec } from '@/sim/spec.ts';
import type { BikeSpec } from '@/sim/spec.ts';
import type { Level } from '@/sim/level.ts';
import type { SimState } from '@/sim/step.ts';
import { renderArt } from './artrender.ts';
import { bakeLevel } from './art/bake.ts';
import { cloneArt, DEFAULT_ART } from './art/params.ts';
import { CONCRETE } from './art/palette.ts';
import { DEFAULT_OVERVIEW, overviewFrame } from './overview.ts';
import type { OverviewParams } from './overview.ts';
import { BOOT_PRESET } from './presets.ts';
import type { Pose } from './render.ts';

/**
 * Card size in CSS pixels, and the aspect is measured rather than assumed.
 *
 * A thumbnail frames the WHOLE level, so a card wider than the level it holds
 * is empty bands top and bottom — and the shipped levels are wide: most sit
 * between 3.5:1 and 7.6:1, with 07-the-chimney the one square-ish outlier at
 * 1.1:1. A 16:9 card filled about a third of itself on average; 8:3 fills about
 * half, costs the wide levels NOTHING (their drawn width is the card width
 * either way) and fits more cards on screen at once.
 */
export const THUMB_W = 176;
export const THUMB_H = 66;

/**
 * Frame the WHOLE level, always. The overview's own `minZoom` is a readability
 * floor for a player who has to find their bike in the picture; here there is
 * no bike to find and cropping a level out of its own thumbnail would be a
 * strictly worse picture, so the floor goes away.
 */
const THUMB_FRAME: OverviewParams = { ...DEFAULT_OVERVIEW, minZoom: 0.05, padding: 0.04 };

/**
 * Quarter of a second of nothing, so the suspension settles and the bike sits
 * on its wheels rather than hanging at the spawn point. Input mask 0 — this is
 * a throwaway sim that no recorder, replay or clock ever sees.
 */
const SETTLE_FRAMES = 24;

function thumbArt(): ReturnType<typeof cloneArt> {
  const a = cloneArt(DEFAULT_ART);
  // The in-canvas game HUD is a level card, a clock and an apple counter. On a
  // 176 px thumbnail it is illegible noise, and the chooser card says all three
  // things in text beside the picture anyway.
  a.hud = 0;
  // Drifting dust animates. A still frame gets a random scatter of specks out
  // of it and nothing else.
  a.motes = 0;
  // A fixed look: adaptive detail exists to defend a frame budget that a
  // one-off offscreen render does not have, and letting it engage would make
  // two thumbnails of the same level differ.
  a.adaptive = 0;
  return a;
}

const ART = thumbArt();
const SPEC: BikeSpec = cloneSpec(BOOT_PRESET.spec);

/** Session cache. Data URLs, keyed by the only identity that matters plus size. */
const cache = new Map<string, string>();

function keyOf(level: Level, w: number, h: number): string {
  return `${level.simHash}|${w}x${h}`;
}

function poseOf(s: SimState): Pose {
  return {
    px: s.px,
    py: s.py,
    ox: s.ox,
    oy: s.oy,
    wx: [s.wx[0], s.wx[1]],
    wy: [s.wy[0], s.wy[1]],
    wspin: [s.wspin[0], s.wspin[1]],
    ax: s.ax,
    ay: s.ay,
  };
}

/** One scratch canvas, reused. Twenty canvases would be twenty GPU surfaces. */
let scratch: HTMLCanvasElement | null = null;

function toUrl(c: HTMLCanvasElement): string {
  // WebP first because these are photographic-ish frames and the PNG of one is
  // several times the size; every browser that refuses it hands back a data URL
  // with the wrong mime, which is the documented way to detect the refusal.
  const webp = c.toDataURL('image/webp', 0.82);
  return webp.startsWith('data:image/webp') ? webp : c.toDataURL('image/png');
}

function drawThumb(level: Level, w: number, h: number): string {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  if (!scratch) scratch = document.createElement('canvas');
  const c = scratch;
  c.width = Math.round(w * dpr);
  c.height = Math.round(h * dpr);
  const ctx = c.getContext('2d', { alpha: false });
  if (!ctx) throw new Error('no 2d context');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const sim = createSim(level, SPEC);
  for (let i = 0; i < SETTLE_FRAMES; i++) {
    if (sim.state.dead || sim.state.finished) break;
    sim.advance(0);
  }
  const frame = overviewFrame(level, { x: sim.state.px, y: sim.state.py }, w, h, THUMB_FRAME);
  const baked = bakeLevel(level, ART, CONCRETE);
  renderArt(
    ctx,
    w,
    h,
    frame,
    sim.world,
    sim.state,
    poseOf(sim.state),
    SPEC,
    {
      debug: false,
      ghost: null,
      ghosts: null,
      // The locator ring is for finding a bike in a live overview. A still
      // picture of a level does not need a target painted on it.
      overview: 0,
      markers: null,
      time: 0,
      measure: false,
    },
    ART,
    baked,
  );
  return toUrl(c);
}

export interface Thumbs {
  /** The picture if it is already drawn, else null. Never renders. */
  peek(level: Level): string | null;
  /**
   * Ask for a picture. Cheap and idempotent: a level already drawn or already
   * queued does nothing. `onReady` fires once, later, on an animation frame.
   */
  request(level: Level): void;
  /** The chooser closed. Drop the queue; keep everything already drawn. */
  stop(): void;
  /** For the bench and for tests of the caller. */
  readonly pending: number;
}

export interface ThumbOpts {
  width?: number;
  height?: number;
  onReady(simHash: string, url: string): void;
}

export function createThumbs(o: ThumbOpts): Thumbs {
  const w = o.width ?? THUMB_W;
  const h = o.height ?? THUMB_H;
  const queue: Level[] = [];
  let raf = 0;

  function pump(): void {
    raf = 0;
    const level = queue.shift();
    if (!level) return;
    const key = keyOf(level, w, h);
    if (!cache.has(key)) {
      try {
        cache.set(key, drawThumb(level, w, h));
      } catch {
        // A thumbnail is decoration. A level that cannot be drawn keeps its
        // placeholder and the card still says everything it said before —
        // failing the whole chooser over a picture would be absurd.
        cache.set(key, '');
      }
    }
    const url = cache.get(key) ?? '';
    if (url) o.onReady(level.simHash, url);
    if (queue.length > 0) raf = requestAnimationFrame(pump);
  }

  return {
    peek(level: Level): string | null {
      return cache.get(keyOf(level, w, h)) || null;
    },
    request(level: Level): void {
      if (cache.has(keyOf(level, w, h))) return;
      if (queue.some((l) => l.simHash === level.simHash)) return;
      queue.push(level);
      if (raf === 0) raf = requestAnimationFrame(pump);
    },
    stop(): void {
      queue.length = 0;
      if (raf !== 0) cancelAnimationFrame(raf);
      raf = 0;
    },
    get pending(): number {
      return queue.length;
    },
  };
}
